import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
    // config per zip: status|delayMs|body
    static Map<String,String[]> cfg = new ConcurrentHashMap<>();
    static List<String> log = Collections.synchronizedList(new ArrayList<>());
    static Map<String,String> q(String s){Map<String,String> m=new HashMap<>(); if(s==null)return m; for(String p:s.split("&")){int i=p.indexOf('='); if(i>0)m.put(URLDecoder.decode(p.substring(0,i),StandardCharsets.UTF_8),URLDecoder.decode(p.substring(i+1),StandardCharsets.UTF_8));} return m;}
    static void send(HttpExchange ex,int st,String b) throws IOException{byte[] d=b.getBytes(StandardCharsets.UTF_8); ex.getResponseHeaders().add("Content-Type","application/json"); ex.sendResponseHeaders(st,d.length); ex.getResponseBody().write(d); ex.close();}
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/set", ex -> { Map<String,String> m=q(ex.getRequestURI().getRawQuery());
            cfg.put(m.get("zip"), new String[]{m.getOrDefault("status","200"), m.getOrDefault("delay","0"), m.getOrDefault("body","{\"price_cents\":3310,\"eta_hours\":41}")}); send(ex,200,"ok"); });
        s.createContext("/log", ex -> { String r; synchronized(log){ r=String.join("\n",log); log.clear(); } send(ex,200,r+"\n"); });
        s.createContext("/v2/quote", ex -> { Map<String,String> m=q(ex.getRequestURI().getRawQuery());
            log.add(ex.getRequestURI().getRawQuery());
            String[] c = cfg.getOrDefault(m.get("zip"), new String[]{"200","0","{\"price_cents\":3310,\"eta_hours\":41}"});
            try { Thread.sleep(Long.parseLong(c[1])); } catch(Exception e){}
            send(ex, Integer.parseInt(c[0]), c[2]); });
        s.start();
        System.out.println("stub up on "+a[0]);
    }
}
